/**
 * The skill's command table is how an Agent discovers what it can call.
 *
 * `--help` is generated by commander from `runCli.ts`, but the table in
 * `skills/digdig/SKILL.md` is hand-copied, and nothing compared the two until
 * this file. The drift that motivated it: `doc-index` and `doc-search` had full
 * documentation in `SOP.md` but never appeared in the table, so an Agent that
 * read only `SKILL.md` could not discover a capability that existed and worked.
 *
 * Neither side of the comparison is a copied list. The registered set comes
 * from `createProgram()`; the documented set is parsed out of the markdown.
 */
import { describe, it, expect } from 'vitest';
import { readFileSync } from 'fs';
import { fileURLToPath } from 'url';
import { createProgram } from '../../src/runCli.js';

/**
 * Commands that are registered but deliberately kept out of the Agent-facing
 * table. Each needs a reason: an unexplained entry is how an unwanted command
 * quietly stays hidden.
 */
const EXEMPT: Array<{ name: string; reason: string }> = [
    {
        name: 'query-graph',
        reason: 'deprecated in runCli.ts:809 in favor of graph-explore + graph-drill',
    },
];

/** Command names the skill table documents: `| \`dg <name> ...\`` rows. */
function documentedCommands(): Set<string> {
    // cli/test/unit -> cli/test -> cli -> repo root, then into skills/.
    const path = fileURLToPath(new URL('../../../skills/digdig/SKILL.md', import.meta.url));
    const source = readFileSync(path, 'utf8');
    const names = new Set<string>();
    for (const match of source.matchAll(/^\|\s*`dg\s+([a-z][a-z-]*)`/gm)) {
        names.add(match[1]);
    }
    return names;
}

/** Command names the CLI actually registers. */
function registeredCommands(): Set<string> {
    return new Set(createProgram().commands.map(command => command.name()));
}

describe('skill command table', () => {
    it('documents every registered command the Agent is meant to use', () => {
        const documented = documentedCommands();
        const missing = [...registeredCommands()]
            .filter(name => !documented.has(name))
            .filter(name => !EXEMPT.some(entry => entry.name === name))
            .sort();

        expect(missing, `SKILL.md is missing: ${missing.join(', ')}`).toEqual([]);
    });

    it('documents no command the CLI does not register', () => {
        const registered = registeredCommands();
        const phantom = [...documentedCommands()].filter(name => !registered.has(name)).sort();

        expect(phantom, `SKILL.md lists commands that do not exist: ${phantom.join(', ')}`).toEqual([]);
    });

    it('keeps every exemption pointing at a command that still exists', () => {
        const registered = registeredCommands();
        const stale = EXEMPT.filter(entry => !registered.has(entry.name)).map(entry => entry.name);

        expect(stale, `stale exemptions, remove or fix: ${stale.join(', ')}`).toEqual([]);
    });

    it('parses a table with commands in it, so a regex break cannot pass silently', () => {
        // A parser that matched nothing would make the first assertion vacuous.
        expect(documentedCommands().size).toBeGreaterThan(20);
    });
});
